const raw = $input.first().json;
let envelope = raw;
if (typeof raw?.data === 'string' && raw.data.includes('data:')) {
  const dataLine = raw.data.split(/\r?\n/).find((l) => l.startsWith('data:'));
  if (dataLine) envelope = JSON.parse(dataLine.slice(5).trim());
}
const textPayload = envelope?.result?.content?.[0]?.text;
if (!textPayload) {
  throw new Error('Unexpected MCP response payload: ' + JSON.stringify(raw));
}
const parsed = JSON.parse(textPayload);
if (!parsed.ok) {
  throw new Error(parsed.message || parsed.error || 'PO Pilot MCP returned an error');
}
if (!parsed.purchase_orders?.length) {
  return [{ json: { hasOrders: false, summary: 'No SKUs crossed reorder points this week.' } }];
}
return parsed.purchase_orders.map((po) => ({
  json: {
    hasOrders: true,
    po_number: po.po_number,
    vendor: po.vendor,
    contact_email: po.contact_email,
    subtotal_usd: po.subtotal_usd,
    total_units: po.total_units,
    moq_notes: po.moq_notes,
    shopify_draft_po_csv: po.shopify_draft_po_csv,
    vendor_email_markdown: po.vendor_email_markdown
  }
}));

